import{d as g,C as s,o as h,c as d,j as n,a as e,E as a,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第16章","description":"《中庸》第 16 章——鬼神之为德：视弗见、听弗闻，而体物不可遗；末以「诚之不可揜」作结。","frontmatter":{"title":"中庸·第16章","description":"《中庸》第 16 章——鬼神之为德：视弗见、听弗闻，而体物不可遗；末以「诚之不可揜」作结。","category":"guide","aliases":["第16章","中庸第16章","鬼神之为德"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-16.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-16.md","lastUpdated":1790316338000}'),u={name:"lizhimingde/sishu-wujing/zhongyong/chapter-16.md"},x=g({...u,setup(p){const r=[{id:"weide",label:"鬼神之为德 · 体物而不可遗",showLabel:!0,sentences:[["子曰：“",{text:"鬼神",glossary:"guishen"},"之",{text:"为德",glossary:"weide"},"，其盛矣乎！视之而弗见，听之而弗闻，",{text:"体物而不可遗",glossary:"tiwu"},"。"]],note:"孔子论鬼神之德，赞其「盛矣乎」！接着三句写它的「隐」与「显」：「视之而弗见，听之而弗闻」——看不见、听不到；而「体物而不可遗」——却体现在万物之中，无法遗漏。"},{id:"jisi",label:"齐明盛服 · 如在其上，如在其左右",showLabel:!0,sentences:[["使天下之人",{text:"齐明盛服",glossary:"zhaiming"},"，以承祭祀。",{text:"洋洋乎",glossary:"yangyang"},"！如在其上，如在其左右。"]],note:"「使天下之人齐明盛服，以承祭祀」（齐＝斋，齐明＝斋戒明洁）——使天下人斋戒明洁、盛服以承奉祭祀。「洋洋乎！如在其上，如在其左右」——那气象洋洋然，好像就在头上、就在左右。此写鬼神之感召。"},{id:"cheng",label:"神之格思 · 微之显，诚之不可揜",showLabel:!0,sentences:[["《诗》曰：‘神之",{text:"格思",glossary:"gesi"},"，不可",{text:"度思",glossary:"duosi"},"！",{text:"矧",glossary:"shen"},"可",{text:"射思",glossary:"yisi"},"！’夫",{text:"微之显",glossary:"weizhixian"},"，",{text:"诚",glossary:"cheng"},"之不可",{text:"揜",glossary:"yan"},"如此夫。”"]],note:"引《诗》「神之格思，不可度思！矧可射思！」——神之来临，不可揣度，何况加以厌弃怠慢（射＝厌弃）？由此归纳出全章之理：「夫微之显，诚之不可揜如此夫」——隐微者自会彰显，诚之不可掩蔽，正是如此。此章以「诚」收束。"}],o=[{id:"guishen",term:"鬼神",pinyin:"guǐ shén",meaning:"朱注引程子：「鬼神，天地之功用，而造化之迹也」；引张子：「鬼神者，二气之良能也」。朱子又谓「至而伸者为神，反而归者为鬼」——不是人格神，而是阴阳二气的作用。"},{id:"weide",term:"为德",pinyin:"wéi dé",meaning:"犹言性情功效。"},{id:"tiwu",term:"体物而不可遗",pinyin:"tǐ wù ér bù kě yí",meaning:"为物之体，而物不能遗弃它。朱注：「物之终始，莫非阴阳合散之所为，是其为物之体，而物所不能遗也。」"},{id:"zhaiming",term:"齐明盛服",pinyin:"zhāi míng shèng fú",meaning:"齐：同「斋」，读 zhāi；明：洁；盛服：礼服。斋戒明洁、穿着礼服。"},{id:"yangyang",term:"洋洋乎",pinyin:"yáng yáng hū",meaning:"流动充满之意。谓鬼神之发见昭著。"},{id:"gesi",term:"格思",pinyin:"gé sī",meaning:"格：至、来；思：语辞。《诗·大雅·抑》句「神之格思」。"},{id:"duosi",term:"度思",pinyin:"duó sī",meaning:"揣度。度：读 duó。"},{id:"shen",term:"矧",pinyin:"shěn",meaning:"况、何况。"},{id:"yisi",term:"射思",pinyin:"yì sī",meaning:"厌怠而不敬。射：读 yì，《诗》作「斁」。"},{id:"weizhixian",term:"微之显",pinyin:"wēi zhī xiǎn",meaning:"由隐微而显明。承第 12 章「费而隐」而言——隐者终显。"},{id:"cheng",term:"诚",pinyin:"chéng",meaning:"朱注：「诚者，真实无妄之谓。」全章落脚于此：阴阳合散无非实者，故其发见不可掩。"},{id:"yan",term:"揜",pinyin:"yǎn",meaning:"同「掩」，掩藏。"}];return(y,i)=>{const l=s("DaoTextReading"),t=s("DaoKeywordCards");return h(),d("div",null,[i[0]||(i[0]=n("h1",{id:"中庸·第16章",tabindex:"-1"},[e("中庸·第16章 "),n("a",{class:"header-anchor",href:"#中庸·第16章","aria-label":'Permalink to "中庸·第16章"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=n("p",null,[e("第十六章讲「鬼神之为德」：无形无声，却是"),n("strong",null,"体物而不可遗"),e("；人因此齐明盛服以承祭祀，「洋洋乎如在其上」。末句是全章的落脚——「"),n("strong",null,"诚之不可揜"),e("」。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"鬼神之为德 · 洋洋如在 · 诚之不可揜",tone:"ink",sections:r,glossary:o,"default-mode":"slips","aria-label":"中庸·第16章 原文"}),i[3]||(i[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"鬼神",pinyin:["guǐ","shén"],meaning:"朱注：程子谓「天地之功用，而造化之迹」；张子谓「二气之良能」；朱子谓「至而伸者为神，反而归者为鬼」——非人格神。"},{term:"体物而不可遗",pinyin:["tǐ","wù","ér","bù","kě","yí"],meaning:"为物之体，而物不能遗弃它。"},{term:"齐明盛服",pinyin:["zhāi","míng","shèng","fú"],meaning:"齐同「斋」（读 zhāi）；明：洁；盛服：礼服。斋戒明洁、穿着礼服。"},{term:"洋洋乎",pinyin:["yáng","yáng","hū"],meaning:"流动充满之意。"}]}),a(t,{items:[{term:"格思",pinyin:["gé","sī"],meaning:"格：至、来。神的来临。"},{term:"度思",pinyin:["duó","sī"],meaning:"度：读 duó。不可揣度。"},{term:"射思",pinyin:["yì","sī"],meaning:"射：读 yì，厌怠不敬。「矧可射思」即何况可以怠慢。"},{term:"微之显",pinyin:["wēi","zhī","xiǎn"],meaning:"由隐微而显明。与第 12 章「费而隐」相对照——隐者终显。"},{term:"诚之不可揜",pinyin:["chéng","zhī","bù","kě","yǎn"],meaning:"揜：同「掩」。朱注：「诚者，真实无妄之谓。阴阳合散，无非实者，故其发见之不可揜如此。」"}]}),i[4]||(i[4]=m('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>鬼神之为德 · 体物而不可遗</strong>：孔子说：「鬼神的性情功效，真是盛大啊！看它看不见，听它听不到，它却是万物的本体，万物都离不开它。」</p><p><strong>齐明盛服 · 如在其上</strong>：使天下的人斋戒明洁、盛服，来承奉祭祀。流动充满啊！好像在人的头上，好像在人的左右。</p><p><strong>神之格思 · 微之显</strong>：《诗经》说：「神的来临，不可揣度！何况可以厌怠不敬呢！」由隐微而显明，诚之不可掩藏，就是这样啊！</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十六章说「鬼神之为德」：它<strong>视之弗见、听之弗闻</strong>，却「体物而不可遗」——万物都由它而成，都离不开它。因此天下之人斋戒盛服以承祭祀，「洋洋乎如在其上，如在其左右」。</p><p>最后一句是全章的归宿：「<strong>夫微之显，诚之不可揜如此夫。</strong>」</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它先给「鬼神」下了定义</strong>：朱注引二程与张载，都说鬼神是阴阳二气的作用与良能，<strong>不是人格化的神明</strong>。这一层务必分清：本章讲的是「不可见的真实作用」。</li><li><strong>「体物而不可遗」把不可见者说成最实在的东西</strong>：它不显形，却是万物的本体。这与第 12 章的「费而隐」正好呼应——隐不是虚无。</li><li><strong>「微之显」是本篇的关键转语</strong>：隐微者终将显明。而它之所以显明，原因只有一个字：<strong>诚</strong>（真实无妄）。朱注：「阴阳合散，无非实者，故其发见之不可揜如此。」</li><li><strong>它替第 20 章埋伏笔</strong>：「诚」这个字在这里第一次被正式提出，正是全篇枢纽的引子。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>不可见 ≠ 不存在</strong>：规律、后果、他人的感受，都属「视弗见、听弗闻」而「体物不可遗」之列。</li><li><strong>敬意的来源</strong>：祭祀之敬，敬的是不可见而实在者；今天可以用同样的态度面对看不见的因果。</li><li><strong>「诚之不可揜」</strong>：真实的东西藏不住，假装的也藏不住——这句话对做人做事都是硬的。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：鬼神的性情功效，真是盛大啊。看它看不见，听它听不到，可它却是万物的本体，万物都离不开它。所以天下人斋戒、洁身、盛服去祭祀，<strong>它流动充满，好像在头上，好像在左右</strong>。</p><p>《诗经》说：神的来临不可揣度，哪能怠慢不敬呢？</p><p>最后一句是诗眼：<strong>由隐微而显明，诚是掩藏不住的。</strong></p><p>换个说法：<strong>看不见的东西，并不因此不实在；而真实的东西，迟早会显出来。</strong> 这就是本章从「鬼神」讲到「诚」的路。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「视之而弗见，听之而弗闻，体物而不可遗」——有哪些「看不见却最实在」的东西，是我常忽略的？</li><li>「诚之不可揜」——我见过哪些藏不住的事？</li><li>「洋洋乎，如在其上，如在其左右」——我对什么怀有这种敬？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-15">中庸·第15章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-17">中庸·第17章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',24))])}}});export{b as __pageData,x as default};
